// src/domains/collections/services/collection-dependents-schema.ts
/**
* Compile the configured extension schema with `removedCollections` seeded
* beside the configured collections. `null` when nothing declares a schema.
*/
async function compileExtensionSchemaWith(input) {
	const { compileExtensionSchema } = await import("./publish-8wCHi1rp.mjs").then((n) => n.r);
	return await compileExtensionSchema({
		dialect: input.dialect,
		plugins: input.config.plugins ?? [],
		config: {
			...input.config,
			collections: [...input.config.collections ?? [], ...input.removedCollections.map((collection) => ({
				slug: collection.slug,
				dbName: collection.tableName,
				fields: collection.fields ?? []
			}))]
		},
		logger: input.logger
	}) ?? null;
}
export { compileExtensionSchemaWith };
